class PacmanException(Exception):
    """Root exception for whole library"""


class InvalidBuildException(PacmanException):
    """Exception raised whenever there is any issue with baseline in any case.

    Doesn't matter if there is no package with such baseline in repository
    or its not matching pattern for given technology.
    """


class InvalidVersionException(InvalidBuildException):
    """Exception raised whenever package has fixed
    number of variations and baseline doesn't match
    any of these variations
    """


class NetworkException(PacmanException):
    """Exception raised whenever any non-VCS
    connection-related problem occurred
    """


class SVNContentError(PacmanException):
    """Exception raised whenever output of svn
    command isn't matching expectations
    """


class SVNContentNotFound(PacmanException):
    """Exception raised whenever there is problem
    with connection to SVN repository
    """


class PackageComponentNotFound(PacmanException):
    """Exception raised whenever one of required components
    like SoftwarePackage or SiteManager is missing from repository
    """


class FileLocked(PacmanException):
    """Exception raised whenever lock file is not accessible to read,
    therefore, there is not possible to check whether another
    instance of downloader is currently working or not
    """
